/** Generated by scripts/generate-insight-audio.mjs into the public `insight-audio` bucket. */
export type InsightAudioLocale = "az" | "ru" | "en" | "de";

export type InsightAudioEntry = {
  slug: string;
  lang: InsightAudioLocale;
  url: string;
  duration_seconds: number;
  bytes: number;
  hash: string;
  voice: string;
  generated_at: string;
};

export const INSIGHT_AUDIO_BUCKET = "insight-audio";
export const INSIGHT_AUDIO_CACHE_TAG = "insight-audio";

const inLanguage: Record<InsightAudioLocale, string> = {
  az: "az-AZ",
  ru: "ru-RU",
  en: "en-US",
  de: "de-DE",
};

export const insightAudioLabels: Record<InsightAudioLocale, string> = {
  az: "Əsasları dinlə",
  ru: "Слушать кратко",
  en: "Listen to key points",
  de: "Kurz anhören",
};

export function insightAudioManifestUrl(supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL) {
  if (!supabaseUrl) return null;
  return `${supabaseUrl.replace(/\/$/, "")}/storage/v1/object/public/${INSIGHT_AUDIO_BUCKET}/manifest.json`;
}

function isAudioLocale(value: unknown): value is InsightAudioLocale {
  return value === "az" || value === "ru" || value === "en" || value === "de";
}

function isEntry(value: unknown): value is InsightAudioEntry {
  if (!value || typeof value !== "object") return false;
  const entry = value as Record<string, unknown>;
  return (
    typeof entry.slug === "string" &&
    isAudioLocale(entry.lang) &&
    typeof entry.url === "string" &&
    entry.url.startsWith("https://") &&
    typeof entry.duration_seconds === "number" &&
    entry.duration_seconds > 0
  );
}

export function findInsightAudio(manifest: unknown, slug: string, locale: string): InsightAudioEntry | null {
  if (!isAudioLocale(locale)) return null;
  const entries = (manifest as { entries?: unknown } | null)?.entries;
  if (!Array.isArray(entries)) return null;
  return (
    entries.find(
      (entry): entry is InsightAudioEntry => isEntry(entry) && entry.slug === slug && entry.lang === locale,
    ) ?? null
  );
}

/** ISO 8601 duration, e.g. 65 -> "PT1M5S". */
export function isoDuration(seconds: number) {
  const total = Math.max(1, Math.round(seconds));
  const minutes = Math.floor(total / 60);
  const rest = total % 60;
  return `PT${minutes ? `${minutes}M` : ""}${rest || !minutes ? `${rest}S` : ""}`;
}

export function formatAudioDuration(seconds: number) {
  const total = Math.max(1, Math.round(seconds));
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, "0")}`;
}

export function insightAudioSchema(entry: InsightAudioEntry, name: string) {
  return {
    "@type": "AudioObject",
    name,
    contentUrl: entry.url,
    encodingFormat: "audio/mpeg",
    duration: isoDuration(entry.duration_seconds),
    inLanguage: inLanguage[entry.lang],
  };
}

/** Reads the manifest through the Next data cache; any failure means "no audio". */
export async function getInsightAudio(slug: string, locale: string): Promise<InsightAudioEntry | null> {
  const url = insightAudioManifestUrl();
  if (!url || !isAudioLocale(locale)) return null;
  try {
    const response = await fetch(url, {
      ...(process.env.NODE_ENV === "development"
        ? { cache: "no-store" as const }
        : { next: { revalidate: 3600, tags: [INSIGHT_AUDIO_CACHE_TAG] } }),
    });
    if (!response.ok) return null;
    return findInsightAudio(await response.json(), slug, locale);
  } catch {
    return null;
  }
}
